contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: no Ether needs to be sent. We expose a dummy boolean input.
    function run(bool unused) public payable {
        require(true);

        // record c's balance before
        uint256 beforeC = address(c).balance;

        bool reverted;
        // perform the state-changing call as a top-level statement
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;

        // General rule: if the call did not revert then c's balance must be zero afterward.
        assert(reverted || afterC == 0);
    }

    // receive Ether to allow capturing selfdestruct transfers if they occur
    receive() external payable {}
}

